/// <summary>
/// The config menu (`TkMenuCtrlConfig`, docs/formats/menu.md "Config
/// menu"), read while it is open.
/// </summary>
public sealed partial class ConfigMenu
{
    /// <summary>
    /// It is open (`main_mask` bit `0x400`; the values below were
    /// read).
    /// </summary>
    public bool Open;
    /// <summary>
    /// The cursor's row (`i8` `0x0186a444`).
    /// </summary>
    public short Cursor;
    /// <summary>
    /// The PC's own row (the remaster's settings, `0x0186a438`): its
    /// texts come from the localisation manager, not the menu text.
    /// </summary>
    public int PcRow;
    /// <summary>
    /// The rows (`0x0186a44c` a list of record pointers, the count
    /// `0x0186a448`).
    /// </summary>
    public List<ConfigRow> Rows = new();

    /// <summary>Reads one from the encoding.</summary>
    public static ConfigMenu Read(ref StateReader r)
    {
        var o = new ConfigMenu();
        o.Open = r.Bool();
        o.Cursor = r.I16();
        o.PcRow = r.I32();
        {
            int n = r.U16();
            o.Rows = new List<ConfigRow>(n);
            for (int i = 0; i < n; i++)
                o.Rows.Add(ConfigRow.Read(ref r));
        }
        return o;
    }
}

