/// <summary>
/// The battle results screen (`TkBtlEndCtrl`, docs/formats/menu.md
/// "Battle end"): AP, gil, items and gear won. FFX has no EXP.
/// </summary>
public sealed partial class BattleEnd
{
    /// <summary>
    /// It runs (`main_mask` bit `0x20000`; the values below were read).
    /// </summary>
    public bool Open;
    /// <summary>
    /// The screen's state (`g_BtlEnd_State` `0x01869f08`, 0..0x2b):
    /// level-ups, the AP count, the gil count, the spoils, the end.
    /// </summary>
    public uint State;
    /// <summary>
    /// The control is done (`g_BtlEndCtrlDone`, byte `0x00c5a068`).
    /// </summary>
    public bool Done;
    /// <summary>
    /// The gil won (`g_TkBtlEndGilWon` `0x02310f6c`).
    /// </summary>
    public uint GilWon;
    /// <summary>
    /// The gil still to count into the party's (`g_TkBtlEndGil` `+4`;
    /// each step pays `gil_step` with `MsPayGIL`).
    /// </summary>
    public uint GilLeft;
    /// <summary>
    /// See `gil_left` (`+0`).
    /// </summary>
    public uint GilStep;
    /// <summary>
    /// The AP each character still has to count (`g_TkBtlEndResults`
    /// `0x02310f20`, 18 `u32` little-endian, counted down to 0).
    /// </summary>
    public byte[] Ap = [];
    /// <summary>
    /// The results rows (`g_TkBtlEndList`, 14-byte entries from
    /// `0x01869f20`, the count byte `0x01869f18`).
    /// </summary>
    public List<BattleEndRow> Rows = new();
    /// <summary>
    /// The items won (`i8` count `0x02310f70`, `u16` ids `0x02310f74`,
    /// `u8` counts `0x02310f84`); `slot` is the row.
    /// </summary>
    public List<ItemStack> Items = new();
    /// <summary>
    /// The gear won (`i8` count `0x02310f72`, up to 6 `u16` ids at
    /// `0x02310f8e`, `MsGetSaveWeapon`'s), `u16` little-endian each.
    /// </summary>
    public byte[] Gear = [];
    /// <summary>
    /// The gear doesn't fit (`0x0186a184`): the exchange pages.
    /// </summary>
    public bool GearFull;
    /// <summary>
    /// The spoils page's side (`0x0186a19c`).
    /// </summary>
    public uint Side;
    /// <summary>
    /// The cursors of the two sides (`0x0186a1a0 + 4 side`; side 0's
    /// relative to `top`).
    /// </summary>
    public int Cursor;
    /// <summary>
    /// See `cursor`.
    /// </summary>
    public int CursorWon;
    /// <summary>
    /// A pick is held (`0x0186a1a8`).
    /// </summary>
    public bool Picked;
    /// <summary>
    /// The gear list's first row shown (`0x0186a190`) and its length
    /// (`0x0186a188`).
    /// </summary>
    public int Top;
    /// <summary>
    /// See `top`.
    /// </summary>
    public int GearList;

    /// <summary>Reads one from the encoding.</summary>
    public static BattleEnd Read(ref StateReader r)
    {
        var o = new BattleEnd();
        o.Open = r.Bool();
        o.State = r.U32();
        o.Done = r.Bool();
        o.GilWon = r.U32();
        o.GilLeft = r.U32();
        o.GilStep = r.U32();
        o.Ap = r.Bytes();
        {
            int n = r.U16();
            o.Rows = new List<BattleEndRow>(n);
            for (int i = 0; i < n; i++)
                o.Rows.Add(BattleEndRow.Read(ref r));
        }
        {
            int n = r.U16();
            o.Items = new List<ItemStack>(n);
            for (int i = 0; i < n; i++)
                o.Items.Add(ItemStack.Read(ref r));
        }
        o.Gear = r.Bytes();
        o.GearFull = r.Bool();
        o.Side = r.U32();
        o.Cursor = r.I32();
        o.CursorWon = r.I32();
        o.Picked = r.Bool();
        o.Top = r.I32();
        o.GearList = r.I32();
        return o;
    }
}

