    /// </summary>
    public bool Shown;
    /// <summary>
    /// Its 2D scene (`+1`, a signed byte).
    /// </summary>
    public short Scene;
    /// <summary>
    /// The layer's id (`i16` `+2`): `scene&lt;scene&gt;layer&lt;id&gt;` in the 2D
    /// model.
    /// </summary>
    public short Id;

    /// <summary>Reads one from the encoding.</summary>
    public static LayerEntry Read(ref StateReader r)
    {
        var o = new LayerEntry();
        o.Shown = r.Bool();
        o.Scene = r.I16();
        o.Id = r.I16();
        return o;
    }
}
